export function ui(names: string) {
  const hooks = names.trim().split(/\s+/).filter(Boolean)
  const entries = hooks.flatMap(hook => (styles[hook]?.split(' ') ?? []).map(name => ({ name, info: precedence[hook]?.[name] })))
  const winners = new Map<string, { name: string; priority: number }>()
  for (const { name, info } of entries) { if (!info) continue; const current = winners.get(info[0]); if (!current || current.priority < info[1]) winners.set(info[0], { name, priority: info[1] }) }
  return [...new Set([...hooks, ...entries.filter(({ name, info }) => !info || winners.get(info[0])?.name === name).map(entry => entry.name)])].join(' ')
}
